INSERT INTO troubleshooting_items (stove_id, category, code_label, title, cause, fix, sort_order, created_at) SELECT id, 'error_code', 'Error #1', 'Fuel Feed Alarm', 'Most likely the stove ran out of fuel, or the flames are adjusted too low.', 'Fill the hopper. Clean the fire pot including its holes and make sure it is installed correctly; clean the firebox and behind the baffles. Make sure the hopper lid is closed and the hopper lid switch is working. Check the vacuum switch hose is not clogged and the vacuum switch is working. Check the auger is not jammed (see Clearing an auger jam). If the code repeats, adjust the trim toward the positive side for more feed and let the stove complete a full shutdown so the new trim takes effect. Still repeating? Contact PelPro support.', 10, CAST(strftime('%s','now') AS INTEGER) * 1000 FROM stoves WHERE name = 'Pellet Pro TSC90' AND NOT EXISTS (SELECT 1 FROM troubleshooting_items WHERE stove_id = stoves.id AND title = 'Fuel Feed Alarm');
--> statement-breakpoint
INSERT INTO troubleshooting_items (stove_id, category, code_label, title, cause, fix, sort_order, created_at) SELECT id, 'error_code', 'Error #2', 'Exhaust Probe Alarm', 'Exhaust temperature is above or below the acceptable range — the exhaust probe has failed, or the flames need to be adjusted.', 'Unplug the stove. Find the exhaust probe connection on the control board (probe is behind the right side panel, held by two Phillips screws). Unplug it, inspect the connection and probe wire for damage, and plug it back in securely. If the wire is damaged, or the code stays, replace the exhaust probe. If a new probe does not fix it, the control board may also need replacing — contact PelPro support.', 20, CAST(strftime('%s','now') AS INTEGER) * 1000 FROM stoves WHERE name = 'Pellet Pro TSC90' AND NOT EXISTS (SELECT 1 FROM troubleshooting_items WHERE stove_id = stoves.id AND title = 'Exhaust Probe Alarm');
--> statement-breakpoint
INSERT INTO troubleshooting_items (stove_id, category, code_label, title, cause, fix, sort_order, created_at) SELECT id, 'error_code', 'Error #3', 'Ambient Probe Alarm', 'Ambient (room) temperature is above or below the acceptable range — the ambient probe has failed.', 'Unplug the stove. Find the ambient probe connection on the control board, unplug it, inspect the connection and wire for damage, and plug it back in securely. Replace the ambient probe if the wire is damaged or the code stays. Factory tip: the ambient probe senses room temperature — if the stove cycles on and off sooner than expected, move the probe further away from the stove and make sure at least 2 inches of it is exposed outside the stove body.', 30, CAST(strftime('%s','now') AS INTEGER) * 1000 FROM stoves WHERE name = 'Pellet Pro TSC90' AND NOT EXISTS (SELECT 1 FROM troubleshooting_items WHERE stove_id = stoves.id AND title = 'Ambient Probe Alarm');
