INSERT INTO troubleshooting_items (stove_id, category, code_label, title, cause, fix, sort_order, created_at) SELECT id, 'error_code', 'Error #4', 'Missed Ignition Alarm', 'The stove has either run out of fuel or the fire pot needs to be cleaned. It is also possible the igniter has failed if the stove is clean.', 'Clean the fire pot including its holes and make sure it is installed correctly; clean the firebox and behind the baffles. Make sure there are pellets in the hopper and the auger is not jammed. Confirm the hopper lid is closed and its switch works, the vacuum switch hose has no debris, and the exhaust probe is properly connected, undamaged, and clean, with the exhaust chamber under the exhaust blower cleaned out. Check the igniter is getting hot and sits in the correct position. Factory igniter tests: with the stove unplugged, the igniter should read roughly 48 ohms across its white wires — if not, replace the igniter. In start-up on HI the igniter wires should read 115–120 VAC — if the ohms are good but there is no voltage, the control board or wire harness needs replacing.', 40, CAST(strftime('%s','now') AS INTEGER) * 1000 FROM stoves WHERE name = 'Pellet Pro TSC90' AND NOT EXISTS (SELECT 1 FROM troubleshooting_items WHERE stove_id = stoves.id AND title = 'Missed Ignition Alarm');
