INSERT INTO troubleshooting_items (stove_id, category, code_label, title, cause, fix, sort_order, created_at) SELECT id, 'error_code', 'Error #5', 'Digital Display Communication Alarm', 'The stove lost power while it was running, or there was a bad connection from the display to the control board. The board may need to be replaced.', 'With the stove off and unplugged, make sure the display communication cable and all connections are connected and there are no damaged wires. Plug the stove back in. If the display lights up, try to put the stove into start-up — if start-up takes no longer than 12 minutes, reset the code and the system is repaired. If the code does not go away, replace the digital display; if it still persists, replace the control board or contact PelPro support.', 50, CAST(strftime('%s','now') AS INTEGER) * 1000 FROM stoves WHERE name = 'Pellet Pro TSC90' AND NOT EXISTS (SELECT 1 FROM troubleshooting_items WHERE stove_id = stoves.id AND title = 'Digital Display Communication Alarm');
--> statement-breakpoint
INSERT INTO troubleshooting_items (stove_id, category, code_label, title, cause, fix, sort_order, created_at) SELECT id, 'error_code', 'Error #7', 'Exhaust Over Temperature Alarm', 'Exhaust temperature over-heat alarm — the stove got too hot. Check the heat exchanger and exhaust system for obstructions, and make sure the flame height is correct.', 'Let the stove cool. Clean the fire pot and firebox, clean behind the baffles, and clean the hopper, stove, and venting completely. Make sure only approved PFI pellet fuel is being used. Clean the convection (room) blower and confirm it comes on — the factory test looks for between 62–115 VAC at the blower depending on the power level the stove is running at. If the blower has voltage but does not run, replace the convection blower; if there is no voltage, replace the control board or contact PelPro support. Do not restart until the stove has cooled and been cleaned.', 60, CAST(strftime('%s','now') AS INTEGER) * 1000 FROM stoves WHERE name = 'Pellet Pro TSC90' AND NOT EXISTS (SELECT 1 FROM troubleshooting_items WHERE stove_id = stoves.id AND title = 'Exhaust Over Temperature Alarm');
