INSERT INTO troubleshooting_items (stove_id, category, code_label, title, cause, fix, sort_order, created_at) SELECT id, 'symptom', NULL, 'Not feeding pellets', 'Hopper empty, hopper lid switch not closing, vacuum switch not closing, an auger jam, or a failed feed motor or control board.', 'Start clean: unplug the stove, clean the fire pot and make sure it is installed correctly, clean the firebox and behind the baffles, check the door seal, clean the chimney pipe, fill the hopper, plug back in, and push start. Then work through it: is the hopper lid closed and its switch working (factory test: continuity across the switch terminals when pressed — anything other than OL is good, otherwise replace the switch)? Is the exhaust blower running? Is the auger dropping pellets — if not, check for a jam and clear it. Is the vacuum switch working (factory test: continuity while drawing on its rubber hose — OL means it is not closing; clean the venting and stove or replace the switch)? Is there 115–120 VAC at the feed motor in PRIME/FEEDING mode, and coming out of the control board? Voltage at the motor but no turn means replace the feed motor; no voltage out of the board means replace the control board.', 100, CAST(strftime('%s','now') AS INTEGER) * 1000 FROM stoves WHERE name = 'Pellet Pro TSC90' AND NOT EXISTS (SELECT 1 FROM troubleshooting_items WHERE stove_id = stoves.id AND title = 'Not feeding pellets');
--> statement-breakpoint
INSERT INTO troubleshooting_items (stove_id, category, code_label, title, cause, fix, sort_order, created_at) SELECT id, 'symptom', NULL, 'Not lighting the fuel', 'Pellets are not dropping, the fire pot is dirty or installed wrong, the igniter is not getting hot or is out of position, or the exhaust blower is not working properly.', 'The stove needs three things to light: air, fuel, and heat — if one is out of balance it may not light. Make sure pellets are dropping into the fire pot (if not, follow Not feeding pellets). Reinstall the fire pot correctly with its holes clear so heated air can reach the pellets. Check the igniter is getting hot and is in the correct position (see the igniter tests under Error #4). Make sure the exhaust blower is working properly and is clean, and there are no airflow obstructions in the stove or venting. Make sure the pellets are good quality.', 110, CAST(strftime('%s','now') AS INTEGER) * 1000 FROM stoves WHERE name = 'Pellet Pro TSC90' AND NOT EXISTS (SELECT 1 FROM troubleshooting_items WHERE stove_id = stoves.id AND title = 'Not lighting the fuel');
--> statement-breakpoint
INSERT INTO troubleshooting_items (stove_id, category, code_label, title, cause, fix, sort_order, created_at) SELECT id, 'symptom', NULL, 'Lazy or sooty flames', 'Dirty stove, hopper, or venting, a door gasket that is not sealing tight, or a trim setting that gives too many pellets and not enough air.', 'Clean the fire pot including its holes, the firebox, behind the baffles, the hopper, and the venting, and make sure the door gasket is making a tight seal. Then adjust the trim: moving trim to the negative side decreases the feed rate and increases exhaust blower RPM (less pellets, more air) — the factory fix for lazy flames, sooty flames, and flames that are too high. Moving trim to the positive side increases feed — for low flames or a fuel feed alarm. The trim change does not take effect until the stove has completed a full shutdown sequence.', 120, CAST(strftime('%s','now') AS INTEGER) * 1000 FROM stoves WHERE name = 'Pellet Pro TSC90' AND NOT EXISTS (SELECT 1 FROM troubleshooting_items WHERE stove_id = stoves.id AND title = 'Lazy or sooty flames');
--> statement-breakpoint
INSERT INTO troubleshooting_items (stove_id, category, code_label, title, cause, fix, sort_order, created_at) SELECT id, 'symptom', NULL, 'No power', 'No power at the outlet, a blown fuse, a tripped snap disc, or a failed control board.', 'Check the outlet has power and the stove is plugged in. Check the fuse on the control board and replace it if it is open. Check the #3 snap disc (behind the left side panel, held by two Phillips screws) — if it has tripped from overheating, reset it per the service guide, and find out why the stove overheated before running it again. Trace power with a multimeter from the cord to the snap disc to the control board; if power reaches the board and nothing lights, replace the control board or contact PelPro support. Only test live circuits if you are comfortable working with 115 VAC — otherwise call a certified installer or electrician.', 130, CAST(strftime('%s','now') AS INTEGER) * 1000 FROM stoves WHERE name = 'Pellet Pro TSC90' AND NOT EXISTS (SELECT 1 FROM troubleshooting_items WHERE stove_id = stoves.id AND title = 'No power');
--> statement-breakpoint
INSERT INTO troubleshooting_items (stove_id, category, code_label, title, cause, fix, sort_order, created_at) SELECT id, 'symptom', NULL, 'Room (convection) blower not coming on', 'The stove has not heated up yet, the blower is dirty or failed, or the control board is not sending it voltage.', 'The room blower only comes on once the exhaust probe reaches about 140 degrees, so give a cold stove time to heat up first. If it still does not come on, clean the convection blower (right side panel, two wing nuts hold it in place). Factory voltage test: with the stove on HI and heated to an estimated 140 degrees, the blower wires should read 60 VAC or higher. Good voltage but no blower means replace the convection blower; no voltage means replace the control board.', 140, CAST(strftime('%s','now') AS INTEGER) * 1000 FROM stoves WHERE name = 'Pellet Pro TSC90' AND NOT EXISTS (SELECT 1 FROM troubleshooting_items WHERE stove_id = stoves.id AND title = 'Room (convection) blower not coming on');
