INSERT INTO troubleshooting_items (stove_id, category, code_label, title, cause, fix, sort_order, created_at) SELECT id, 'symptom', NULL, 'Exhaust blower not coming on', 'A dirty or failed exhaust blower, or no voltage from the control board — without it there is no vacuum, so the vacuum switch will not close and the auger will not feed.', 'Clean the exhaust blower and its housing (left side panel; a Phillips screwdriver is needed to remove the blower from the housing). Factory voltage test: check for voltage at the exhaust blower wires during start-up with a multimeter set to VAC. Voltage present but the blower does not run means replace the exhaust blower; no voltage means work through the power tracing and control board tests in the service guide, or contact PelPro support.', 150, CAST(strftime('%s','now') AS INTEGER) * 1000 FROM stoves WHERE name = 'Pellet Pro TSC90' AND NOT EXISTS (SELECT 1 FROM troubleshooting_items WHERE stove_id = stoves.id AND title = 'Exhaust blower not coming on');
