INSERT INTO troubleshooting_items (stove_id, category, code_label, title, cause, fix, sort_order, created_at) SELECT id, 'symptom', NULL, 'Clearing an auger jam', 'Pellets, fines, or a foreign object stuck in the auger — often after damp pellets or a bag fragment gets into the hopper.', 'Factory procedure: 1) Turn the stove off and let it shut down completely, then unplug it. 2) Open the hopper lid, remove the pellets, and vacuum the hopper of remaining pellets and dust. 3) Remove the four screws holding the auger plate (a putty knife may be needed to loosen it). 4) Check the auger for obstructions, remove them, and vacuum out pellet bits and dust — the auger should then move a quarter to half a turn. 5) Replace the auger plate and add pellets — only half a bag until you are sure the auger is free. 6) PRIME the stove from OFF (settings button, then press and hold the DOWN arrow until the display reads FEEDING) to refill the auger tube; the feed motor runs about 2 minutes.', 160, CAST(strftime('%s','now') AS INTEGER) * 1000 FROM stoves WHERE name = 'Pellet Pro TSC90' AND NOT EXISTS (SELECT 1 FROM troubleshooting_items WHERE stove_id = stoves.id AND title = 'Clearing an auger jam');
