INSERT INTO troubleshooting_items (stove_id, category, code_label, title, cause, fix, sort_order, created_at) SELECT id, 'error_code', 'E42', 'Low pressure at the vacuum switch', 'Low pressure detected at the vacuum switch. The vacuum switch is a safety switch behind the left door, fastened to the base — a leak, an open firebox door, a blocked flue, or an unsealed ash drawer can drop the firebox pressure and shut the stove off.', '1) Check that the door, and the ash drawer if present, has been closed properly. 2) Check that there is nothing obstructing the exhaust duct, and that the duct is not leaking. 3) Check that the combustion fan is not broken. Caution from the factory: if overheating has occurred (E42 and E6), an inspection, maintenance, and/or cleaning must occur before the stove can safely be operated again. Press Confirm to clear the code, then restart.', 30, CAST(strftime('%s','now') AS INTEGER) * 1000 FROM stoves WHERE name = 'Master Force H140XL' AND NOT EXISTS (SELECT 1 FROM troubleshooting_items WHERE stove_id = stoves.id AND title = 'Low pressure at the vacuum switch');
