INSERT INTO troubleshooting_items (stove_id, category, code_label, title, cause, fix, sort_order, created_at) SELECT id, 'error_code', 'E6', 'High temperature sensor failure', 'Failure at the high temperature sensor, located below the pellet hopper. A high temperature limiter sits on the bottom of the hopper and shuts the stove off if it is exposed to temperatures higher than 185°F.', '1) Let the stove cool down and clean the stove thoroughly before restarting. 2) Check that the switch is not broken. 3) If the code persists or continues to reoccur, halt operation of the stove and call customer service (Enerco Group, 1-833-950-1184). Caution from the factory: if overheating has occurred (E42 and E6), an inspection, maintenance, and/or cleaning must occur before the stove can safely be operated again.', 40, CAST(strftime('%s','now') AS INTEGER) * 1000 FROM stoves WHERE name = 'Master Force H140XL' AND NOT EXISTS (SELECT 1 FROM troubleshooting_items WHERE stove_id = stoves.id AND title = 'High temperature sensor failure');
