INSERT INTO troubleshooting_items (stove_id, category, code_label, title, cause, fix, sort_order, created_at) SELECT id, 'symptom', NULL, 'Not enough hot air circulating', 'The fuel is inadequate, the circulating blower is set too slow or is compromised, the motherboard that connects to the blower is broken, or the heat exchange tubes or flue pass are dirty.', 'Use the pellet fuel specified by the manual. If the blower is broken, change out the blower; if the motherboard that connects to the blower is broken, change out the motherboard. Clean the heat exchanger tubes and the flue pass.', 180, CAST(strftime('%s','now') AS INTEGER) * 1000 FROM stoves WHERE name = 'Master Force H140XL' AND NOT EXISTS (SELECT 1 FROM troubleshooting_items WHERE stove_id = stoves.id AND title = 'Not enough hot air circulating');
